// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        // The fuzzer supplies the addresses and value; the callee must be a contract that reverts on any call.
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool ok;
        try c.transfer(from, address(reverter), tos, amount) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference C must revert because the external call to the failing callee fails.
        // The bug returns true, so this assertion passes on the reference but fails on the bug.
        assertTrue(!ok, "C must revert when an external call fails");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
